
import React, { forwardRef, useEffect, useRef, useState } from 'react';
import './PlacaOferta.css';

const PlacaOferta = forwardRef(({ titulo, precoInicial, precoReal, precoCentavos, dataInicial, dataFinal }, ref) => {

    const tituloRef = useRef(null);
    const containerRef = useRef(null);
    const [fontSize, setFontSize] = useState(100); // tamanho inicial da fonte

    // Ajusta o font-size do título
    useEffect(() => {
      const ajustarFonte = () => {
        const tituloEl = tituloRef.current;
        const containerEl = containerRef.current;

        if (!tituloEl || !containerEl) return;

        let size = 100;
        tituloEl.style.fontSize = `${size}px`;

        while (
          (tituloEl.scrollHeight > containerEl.clientHeight ||
            tituloEl.scrollWidth > containerEl.clientWidth) &&
          size > 5
        ) {
          size -= 1;
          tituloEl.style.fontSize = `${size}px`;
        }

        setFontSize(size);
      };

      ajustarFonte();
    }, [titulo]); 

  return (
    <div ref={ref} className="placa-oferta">
        <span className="sloganOferta">OFERTA</span>
        <div className="corpoOferta">
          <div
              className="tituloOfertaContainer"
              ref={containerRef}
              style={{
                width: '100%',
                height: '50mm', // defina altura conforme desejado
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                overflow: 'hidden',
                textAlign: 'center',
                border: '1px dashed red;' /* opcional, para visualizar limites */
              }}
          >
            <span 
              ref={tituloRef}
              className="tituloOferta"
              style={{
                fontSize: `${fontSize}px`,
                lineHeight: 1.1,
                wordBreak: 'break-word',
              }}
            >
              {titulo}
            </span>
          </div>
            {(precoInicial && precoInicial !== "-") && <span className='cifraoOferta'>&nbsp;De&nbsp;<b>{precoInicial} </b>. Por R$</span>}
            {!precoInicial && <span className='cifraoOferta'>&nbsp; R$</span>}
            <div className='precoOferta'>

              <span 
                className="precoOfertaReal"
              >
                {precoReal} 
              </span>
              <span className="precoOfertaCentavos">,{precoCentavos}</span>
            </div>    
        </div>
        {dataInicial === dataFinal ? (
            <span className='footerOferta'>Oferta válida para o dia {dataFinal}.</span>
          ) : (
            <span className='footerOferta'>Oferta válida de {dataInicial} até {dataFinal}.</span>
          )
        }
    </div>
  );
});

export default PlacaOferta; 