import React, { forwardRef, useEffect, useRef, useState } from 'react';
import './PlacaAproveiteDupla.css';

const PlacaAproveiteDupla = forwardRef(({ titulo, precoReal, precoCentavos, 
    titulo2, precoReal2, precoCentavos2 }, ref) => {
            const tituloRef = useRef(null);
            const containerRef = useRef(null);
            const [fontSize, setFontSize] = useState(100); // tamanho inicial da fonte
            const tituloRef2 = useRef(null);
            const containerRef2 = useRef(null);
            const [fontSize2, setFontSize2] = useState(100); // tamanho inicial da fonte
        
            // Ajusta o font-size do título
            useEffect(() => {
              const ajustarFonte = () => {
                const tituloEl = tituloRef.current;
                const containerEl = containerRef.current;
        
                if (!tituloEl || !containerEl) return;
        
                let size = 100;
                tituloEl.style.fontSize = `${size}px`;
        
                while (
                  (tituloEl.scrollHeight > containerEl.clientHeight ||
                    tituloEl.scrollWidth > containerEl.clientWidth) &&
                  size > 5
                ) {
                  size -= 1;
                  tituloEl.style.fontSize = `${size}px`;
                }
        
                setFontSize(size);
              };
        
              ajustarFonte();
            }, [titulo]);
        
            useEffect(() => {
              const ajustarFonte = () => {
                const tituloE2 = tituloRef2.current;
                const containerE2 = containerRef2.current;
        
                if (!tituloE2 || !containerE2) return;
        
                let size = 100;
                tituloE2.style.fontSize = `${size}px`;
        
                while (
                  (tituloE2.scrollHeight > containerE2.clientHeight ||
                    tituloE2.scrollWidth > containerE2.clientWidth) &&
                  size > 5
                ) {
                  size -= 1;
                  tituloE2.style.fontSize = `${size}px`;
                }
        
                setFontSize2(size);
              };
        
              ajustarFonte();
            }, [titulo2]);
    return (

            <div ref={ref} className="placa-aproveiteDupla">
                <span className="sloganAproveiteDupla">APROVEITE</span>
                <div className="corpoAproveiteDupla">
                    <div
                        className="tituloAproveiteDuplaContainer"
                        ref={containerRef}
                        style={{
                        width: '100%',
                        height: '60mm', // defina altura conforme desejado
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        overflow: 'hidden',
                        textAlign: 'center',
                        border: '1px dashed red;' /* opcional, para visualizar limites */
                        }}
                    >
                    <span 
                        ref={tituloRef}
                        className='tituloAproveiteDupla'
                        style={{
                            fontSize: `${fontSize}px`,
                            lineHeight: 1.1,
                            wordBreak: 'break-word',
                            }}
                        >
                    {titulo}
                    </span>
                    </div>
                    <div className='precoAproveiteDupla'>
                    <span className="precoAproveiteRealDupla">R${precoReal} </span>
                    <span className="precoAproveiteCentavosDupla">,{precoCentavos}</span>
                    </div>    
                </div>
                <span className="sloganAproveiteDupla">APROVEITE</span>
                <div className="corpoAproveiteDupla">
                    <div
                        className="tituloAproveiteDuplaContainer"
                        ref={containerRef2}
                        style={{
                        width: '100%',
                        height: '60mm', // defina altura conforme desejado
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        overflow: 'hidden',
                        textAlign: 'center',
                        border: '1px dashed red;' /* opcional, para visualizar limites */
                        }}
                    >
                    <span 
                        ref={tituloRef2}
                        className='tituloAproveiteDupla'
                        style={{
                            fontSize: `${fontSize2}px`,
                            lineHeight: 1.1,
                            wordBreak: 'break-word',
                        }}
                        >
                        {titulo2}
                        </span>
                    </div>
                    <div className='precoAproveiteDupla'>
                    <span className="precoAproveiteRealDupla">R${precoReal2} </span>
                    <span className="precoAproveiteCentavosDupla">,{precoCentavos2}</span>
                    </div>    
                </div>
            </div>
    )
})
 
export default PlacaAproveiteDupla;