import React, { forwardRef, useEffect, useRef, useState } from 'react';
import './PlacaOfertaDupla.css';

const PlacaOfertaDupla = forwardRef(({ titulo, precoInicial, precoReal, precoCentavos, dataInicial, dataFinal,
    titulo2, precoInicial2, precoReal2, precoCentavos2, dataInicial2, dataFinal2
 }, ref) => {

    const tituloRef = useRef(null);
    const containerRef = useRef(null);
    const [fontSize, setFontSize] = useState(100); // tamanho inicial da fonte
    const tituloRef2 = useRef(null);
    const containerRef2 = useRef(null);
    const [fontSize2, setFontSize2] = useState(100); // tamanho inicial da fonte

    // Ajusta o font-size do título
    useEffect(() => {
      const ajustarFonte = () => {
        const tituloEl = tituloRef.current;
        const containerEl = containerRef.current;

        if (!tituloEl || !containerEl) return;

        let size = 100;
        tituloEl.style.fontSize = `${size}px`;

        while (
          (tituloEl.scrollHeight > containerEl.clientHeight ||
            tituloEl.scrollWidth > containerEl.clientWidth) &&
          size > 5
        ) {
          size -= 1;
          tituloEl.style.fontSize = `${size}px`;
        }

        setFontSize(size);
      };

      ajustarFonte();
    }, [titulo]);

    useEffect(() => {
      const ajustarFonte = () => {
        const tituloE2 = tituloRef2.current;
                const containerE2 = containerRef2.current;
        
                if (!tituloE2 || !containerE2) return;
        
                let size = 100;
                tituloE2.style.fontSize = `${size}px`;
        
                while (
                  (tituloE2.scrollHeight > containerE2.clientHeight ||
                    tituloE2.scrollWidth > containerE2.clientWidth) &&
                  size > 5
                ) {
                  size -= 1;
                  tituloE2.style.fontSize = `${size}px`;
                }
        
                setFontSize2(size);
      };

      ajustarFonte();
    }, [titulo2]);

  return (
    <div ref={ref} className="placa-ofertaDupla">
        <span className="sloganOfertaDupla">OFERTA</span>
        <div className="corpoOfertaDupla">
            <div
                className="tituloOfertaContainer"
                ref={containerRef}
                style={{
                  width: '100%',
                  height: '40mm', // defina altura conforme desejado
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  overflow: 'hidden',
                  textAlign: 'center',
                }}
            >
              <span 
                ref={tituloRef}
                className='tituloOfertaDupla'
                style={{
                  fontSize: `${fontSize}px`,
                  lineHeight: 1.1,
                  wordBreak: 'break-word',
                }}
              >
                {titulo}
              </span>
            </div>
            {(precoInicial && precoInicial !== "-") && <span className='cifraoOfertaDupla'>&nbsp;De &nbsp;<b>{precoInicial}</b>. Por:</span>}
            <div className='precoOfertaDupla'>
              <span className="precoOfertaRealDupla">R${precoReal}</span>
              <span className="precoOfertaCentavosDupla">,{precoCentavos}</span>
            </div>    
        </div>
        {dataInicial === dataFinal && <span className='footerOfertaDupla'>Oferta válida para o dia {dataFinal}.</span>}
        {dataInicial !== dataFinal && <span className='footerOfertaDupla'>Oferta válida de {dataInicial} até {dataFinal}.</span>}
        <span className="sloganOfertaDupla">OFERTA</span>
        <div className="corpoOfertaDupla">
          <div
                className="tituloOfertaContainer"
                ref={containerRef2}
                style={{
                  width: '100%',
                  height: '40mm', // defina altura conforme desejado
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  overflow: 'hidden',
                  textAlign: 'center',
                  border: '1px dashed red;' /* opcional, para visualizar limites */
                }}
            >
            <span 
              ref={tituloRef2}
              className='tituloOfertaDupla'
              style={{
                fontSize: `${fontSize2}px`,
                lineHeight: 1.1,
                wordBreak: 'break-word',
              }}
              >
                {titulo2}
              </span>
            </div>
            {(precoInicial2 && precoInicial2 !== "-") && <span className='cifraoOfertaDupla'>&nbsp;De &nbsp;<b> {precoInicial2} </b>. Por:</span>}
            <div className='precoOfertaDupla'>
              <span className="precoOfertaRealDupla">R${precoReal2}</span>
              <span className="precoOfertaCentavosDupla">,{precoCentavos2}</span>
            </div>    
        </div>
        {dataInicial2 === dataFinal2 ? (
            <span className='footerOfertaDupla'>Oferta válida para o dia {dataFinal2}.</span>
          ) : (
            <span className='footerOfertaDupla'>Oferta válida de {dataInicial2} até {dataFinal2}.</span>
          )
        }
    </div>
  );
});
 
export default PlacaOfertaDupla;