import React, { forwardRef, useEffect, useRef, useState } from 'react';
import './PlacaAproveite.css';

const PlacaAproveite = forwardRef(({ titulo, precoReal, precoCentavos, dataInicial, dataFinal }, ref) => {
  
    const tituloRef = useRef(null);
    const containerRef = useRef(null);
    const [fontSize, setFontSize] = useState(100); // tamanho inicial da fonte
    // Ajusta o font-size do título
    useEffect(() => {
      const ajustarFonte = () => {
        const tituloEl = tituloRef.current;
        const containerEl = containerRef.current;

        if (!tituloEl || !containerEl) return;

        let size = 100;
        tituloEl.style.fontSize = `${size}px`;

        while (
          (tituloEl.scrollHeight > containerEl.clientHeight ||
            tituloEl.scrollWidth > containerEl.clientWidth) &&
          size > 5
        ) {
          size -= 1;
          tituloEl.style.fontSize = `${size}px`;
        }

        setFontSize(size);
      };

      ajustarFonte();
    }, [titulo]);  
  
  return (
    <div ref={ref} className="placa-aproveite">
        <span className="sloganAproveite">APROVEITE</span>
        <div className="corpoAproveite">
          <div
              className="tituloAproveiteContainer"
              ref={containerRef}
              style={{
                width: '100%',
                height: '50mm', // defina altura conforme desejado
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                overflow: 'hidden',
                textAlign: 'center',
                border: '1px dashed red;' /* opcional, para visualizar limites */
              }}
          >
            <span 
              ref={tituloRef}
              className='tituloAproveite'
              style={{
                fontSize: `${fontSize}px`,
                lineHeight: 1.1,
                wordBreak: 'break-word',
              }}
            >
              {titulo}
              </span>
            </div>
            <span className='cifraoAproveite'>&nbsp; R$</span>
            <div className='precoAproveite'>
              <span className="precoAproveiteReal">{precoReal} </span>
              <span className="precoAproveiteCentavos">,{precoCentavos}</span>
            </div>    
        </div>
    </div>
  );
});
 
export default PlacaAproveite;